{
  "questions": [
    {
      "index": 6,
      "slo_id": "S6",
      "level": "apply",
      "question": "What is the improper fraction $\\frac{9}{5}$ written as a Mixed Number?",
      "options": [
        "$1\\frac{4}{5}$",
        "$1\\frac{1}{5}$",
        "$9\\frac{1}{5}$"
      ],
      "correct_index": 0,
      "explanation": "To convert an improper fraction to a mixed number, divide the numerator by the denominator. The quotient is the whole number, the remainder is the new numerator, and the denominator stays the same.",
      "selected_because": "converting an improper fraction to a mixed number using a lesson example",
      "distractor_misconceptions": {
        "1": "remainder as new denominator",
        "2": "numerator as whole number"
      },
      "option_feedback": {
        "correct": "Excellent! When you divide 9 by 5, you get 1 with a remainder of 4, so it is $1\\frac{4}{5}$.",
        "wrong": {
          "1": "This looks like you divided 9 by 5 and used the remainder as the denominator. Remember, the denominator stays the same as in the original fraction.",
          "2": "It seems you used the original numerator as the whole number. To find the whole number part, you need to divide the numerator by the denominator."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Four pieces make one whole, and three pieces are left, so it is one and three fourths.",
      "teaching_error": null
    },
    {
      "index": 7,
      "slo_id": "S4",
      "level": "understand",
      "question": "Which of these fractions is a Proper Fraction?",
      "options": [
        "$\\frac{2}{5}$",
        "$\\frac{7}{4}$",
        "$\\frac{9}{5}$"
      ],
      "correct_index": 0,
      "explanation": "A Proper Fraction is a fraction where the numerator is smaller than the denominator, meaning its value is less than one whole.",
      "selected_because": "identifying a proper fraction from lesson examples",
      "distractor_misconceptions": {
        "1": "confuses proper with improper fraction",
        "2": "confuses proper with improper fraction"
      },
      "option_feedback": {
        "correct": "That's right! In a Proper Fraction like $\\frac{2}{5}$, the top number (numerator) is smaller than the bottom number (denominator).",
        "wrong": {
          "1": "This is an Improper Fraction because the numerator is larger than the denominator. Remember, for a Proper Fraction, the top number must be smaller.",
          "2": "This is an Improper Fraction, not a Proper Fraction. A Proper Fraction has a numerator that is smaller than its denominator, like $\\frac{2}{5}$."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "In all of these the top number is smaller than the bottom number, so the value of the fraction is less than one whole.",
      "teaching_error": null
    }
  ]
}
